 "content": "def transform(grid):
    """Copy the colored pattern around one 5 marker to the other 5 marker."""
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) < 2:
        return out

    h, w = len(grid), len(grid[0])
    def nearby_count(pos):
        r0, c0 = pos
        return sum(
            1 for r in range(max(0, r0 - 3), min(h, r0 + 4))
            for c in range(max(0, c0 - 3), min(w, c0 + 4))
            if (r, c) != pos and grid[r][c] != 0 and grid[r][c] != 5
        )

    source = max(markers, key=nearby_count)
    target = min((p for p in markers if p != source), key=nearby_count)
    sr, sc = source
    tr, tc = target

    # Translate every non-marker colored cell by the offset between the two 5s.
    # The source drawing stays in place; the target 5 is replaced by the drawing.
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value != 0 and value != 5:
                rr, cc = tr + (r - sr), tc + (c - sc)
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = value
    out[tr][tc] = 0
    return out
